css:
/* BFD Agora for T3. Tokens: agora-platform app/src/styles/brand-tokens.css. State by thin rules and type, never fills. */
:root { --bfd-ink:#171717; --bfd-paper:#FAFAFA; --bfd-line:#D4D4D8; --bfd-muted:#64646D; --bfd-gold:#805B00; --bfd-mint:#0C7243; --bfd-stuck:#B52222; --bfd-ease: cubic-bezier(.2,.7,.2,1); --bfd-wm: url("data:image/svg+xml;utf8,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 2097 700'%3E%3Cg fill='%23F4F4F5'%3E%3Cpath transform='translate(-57,700) scale(1,-1)' d='M747 193Q747 101 671.0 50.5Q595 0 451 0H57V700H431Q571 700 642.5 650.0Q714 600 714 517Q714 468 689.5 429.0Q665 390 617 366Q679 343 713.0 299.0Q747 255 747 193ZM289 535V431H399Q476 431 476 483Q476 535 399 535ZM509 220Q509 275 431 275H289V165H431Q509 165 509 220Z'/%3E%3Cpath transform='translate(686,700) scale(1,-1)' d='M293 522V402H585V224H293V0H57V700H626V522Z'/%3E%3Cpath transform='translate(1300,700) scale(1,-1)' d='M57 700H402Q519 700 608.5 657.5Q698 615 747.5 536.0Q797 457 797 350Q797 243 747.5 164.0Q698 85 608.5 42.5Q519 0 402 0H57ZM392 184Q468 184 513.5 227.5Q559 271 559 350Q559 429 513.5 472.5Q468 516 392 516H293V184Z'/%3E%3C/g%3E%3C/svg%3E"); }
.dark { --bfd-ink:#F4F4F5; --bfd-paper:#18181B; --bfd-line:#2E2E33; --bfd-muted:#A1A1AA; --bfd-gold:#FFC800; --bfd-mint:#5AE09A; --bfd-stuck:#FF8787; }
body { counter-reset: bfdneeds bfdupd bfdlive; }
html, body, button, input, textarea, select, .composer-tiptap, .chat-markdown { font-family: "Montserrat", ui-sans-serif, system-ui, sans-serif !important; }
.chat-markdown h1, .chat-markdown h2, .chat-markdown h3 { font-weight: 700 !important; letter-spacing: 0 !important; }

/* Brand */
a[aria-label="T3 Code home"] > * { display: none !important; }
a[aria-label="T3 Code home"] { display: inline-flex !important; align-items: center !important; gap: 0 !important; }
a[aria-label="T3 Code home"]::before { content: ""; display: inline-block; width: 57px; height: 19px; flex-shrink: 0; background: var(--bfd-ink); -webkit-mask: var(--bfd-wm) no-repeat left center / contain; mask: var(--bfd-wm) no-repeat left center / contain; }
a[aria-label="T3 Code home"]::after { content: "Agora"; margin-left: 12px; padding-left: 12px; border-left: 1px solid var(--bfd-line); font: 600 16px/19px "Montserrat", sans-serif; letter-spacing: 0; color: var(--bfd-ink); white-space: nowrap; }

/* No history arrows: Keith uses the hotkeys */
[aria-label="Go back"], [aria-label="Go forward"] { display: none !important; }
:has(> [data-environment-identification]), [data-environment-identification] { display: none !important; }

/* Surfaces */
[data-user-message-bubble] { border: 1px solid var(--bfd-line) !important; border-radius: 12px !important; }
[data-slot="composer-host"] { border-radius: 12px !important; border: 1px solid var(--bfd-line) !important; transition: border-color .18s var(--bfd-ease), box-shadow .18s var(--bfd-ease); }
[data-slot="composer-host"]:focus-within { border-color: var(--bfd-muted) !important; box-shadow: 0 0 0 3px color-mix(in srgb, var(--bfd-ink) 7%, transparent); }
[data-thread-details-card] { border: 1px solid var(--bfd-line) !important; border-radius: 12px !important; }
[data-chat-header] { border-bottom: 1px solid var(--bfd-line) !important; }
[data-slot="dialog-popup"], [data-slot="popover-popup"], [data-slot="menu-popup"] { border-radius: 12px !important; border: 1px solid var(--bfd-line) !important; }
[data-slot="tooltip-popup"] { border-radius: 6px !important; font-weight: 500; }
[data-slot="button"] { border-radius: 8px; }
[data-slot="project-monogram"] svg { filter: grayscale(1) contrast(1.15); }
.chat-markdown-codeblock { border: 1px solid var(--bfd-line) !important; border-radius: 8px !important; }
svg.lucide { stroke-width: 1.75; }
::-webkit-scrollbar-thumb { background: var(--bfd-line); border-radius: 8px; }
::selection { background: color-mix(in srgb, var(--bfd-gold) 32%, transparent); }

/* Sidebar, after Agora's AdminSidebar: quiet rows, paper card and gold inset rule for attention, state as a thin inset rule */
[data-slot="sidebar"] li:has([data-testid$="-shelf-toggle"]), [data-slot="sidebar"] :has(> [data-testid$="-shelf-toggle"]) { margin-top: 16px !important; padding-top: 10px; border-top: 1px solid var(--bfd-line); }
[data-testid$="-shelf-toggle"] { font-weight: 500 !important; color: var(--bfd-muted) !important; transition: color .14s var(--bfd-ease); }
[data-testid$="-shelf-toggle"]:hover { color: var(--bfd-ink) !important; }
[data-thread-item] [data-sidebar-row] { border-radius: 6px !important; border: 1px solid transparent; background-repeat: no-repeat !important; background-position: left center !important; background-size: 2px calc(100% - 16px) !important; transition: background-color .16s var(--bfd-ease), border-color .16s var(--bfd-ease), background-size .22s var(--bfd-ease), transform .08s var(--bfd-ease); }
[data-thread-item] [data-sidebar-row]:hover { background-color: color-mix(in srgb, var(--bfd-ink) 6%, transparent) !important; background-size: 2px calc(100% - 8px) !important; }
[data-thread-item] [data-sidebar-row]:active { transform: scale(.992); }
[data-thread-item] [data-sidebar-row]:focus-visible { outline: 2px solid var(--bfd-gold) !important; outline-offset: -2px; }
[data-thread-item] [data-sidebar-row]:is([aria-current="page"],[aria-current="true"]) { border-color: var(--bfd-line) !important; background-color: var(--bfd-paper) !important; }
[data-thread-item]:has([data-sidebar-row]:is([aria-label*=", Working"],[aria-label*=", Goal"],[aria-label*=", Setting up"],[aria-label*=", Waiting"]):not([aria-label^="NEEDS KEITH:" i],[aria-label*=", Approval"],[aria-label*=", Input"],[aria-label*=", Request"])) { content-visibility: visible !important; counter-increment: bfdlive; }
[data-thread-item] [data-sidebar-row]:is([aria-label*=", Working"],[aria-label*=", Goal"],[aria-label*=", Setting up"],[aria-label*=", Waiting"]) { background-image: linear-gradient(var(--bfd-mint),var(--bfd-mint)) !important; }
[data-thread-item]:has([data-sidebar-row] button[aria-label="Settle thread"]):not(:has([data-sidebar-row]:is([aria-label^="NEEDS KEITH:" i],[aria-label*=", Approval"],[aria-label*=", Input"],[aria-label*=", Request"],[aria-label^="NEEDS "],[aria-label^="WAITING:"],[aria-label^="BLOCKED:"],[aria-label*=", Working"],[aria-label*=", Goal"],[aria-label*=", Setting up"],[aria-label*=", Waiting"],[aria-label*=", Failed"],[aria-label*=", Limited"],[aria-label*=", Woke"],[data-sidebar-parent="shelf:working"],[data-sidebar-parent="shelf:snoozed"],[data-sidebar-parent="shelf:settled"]))):not(:has(button[aria-label="Discard draft"])) { content-visibility: visible !important; counter-increment: bfdupd; }
[data-thread-item] [data-sidebar-row]:has(button[aria-label="Settle thread"]):not([aria-label^="NEEDS KEITH:" i],[aria-label*=", Approval"],[aria-label*=", Input"],[aria-label*=", Request"],[aria-label^="NEEDS "],[aria-label^="WAITING:"],[aria-label^="BLOCKED:"],[aria-label*=", Working"],[aria-label*=", Goal"],[aria-label*=", Setting up"],[aria-label*=", Waiting"],[aria-label*=", Failed"],[aria-label*=", Limited"],[aria-label*=", Woke"],[data-sidebar-parent="shelf:working"],[data-sidebar-parent="shelf:snoozed"],[data-sidebar-parent="shelf:settled"]):not(:has(button[aria-label="Discard draft"])) { background-image: linear-gradient(var(--bfd-ink),var(--bfd-ink)) !important; }
[data-thread-item]:has([data-sidebar-row]:is([aria-label^="NEEDS KEITH:" i],[aria-label*=", Approval"],[aria-label*=", Input"],[aria-label*=", Request"])) { content-visibility: visible !important; counter-increment: bfdneeds; }
[data-thread-item] [data-sidebar-row]:is([aria-label^="NEEDS KEITH:" i],[aria-label*=", Approval"],[aria-label*=", Input"],[aria-label*=", Request"]) { background-color: var(--bfd-paper) !important; border-color: var(--bfd-line) !important; background-image: linear-gradient(var(--bfd-gold),var(--bfd-gold)) !important; }
[data-thread-item] [data-sidebar-row]:is([aria-label^="NEEDS KEITH:" i],[aria-label*=", Approval"],[aria-label*=", Input"],[aria-label*=", Request"]):hover { background-color: color-mix(in srgb, var(--bfd-ink) 4%, var(--bfd-paper)) !important; border-color: color-mix(in srgb, var(--bfd-gold) 45%, var(--bfd-line)) !important; }
li[data-thread-item]:nth-child(1 of :has([data-sidebar-row]:is([aria-label^="NEEDS KEITH:" i],[aria-label*=", Approval"],[aria-label*=", Input"],[aria-label*=", Request"])))::before { content: "Needs you"; display: block; padding: 6px 12px 6px; font: 500 12px/16px "Montserrat", sans-serif; color: var(--bfd-muted); }
li:nth-child(1 of [data-thread-item]:has([data-sidebar-row] button[aria-label="Settle thread"]):not(:has([data-sidebar-row]:is([aria-label^="NEEDS KEITH:" i],[aria-label*=", Approval"],[aria-label*=", Input"],[aria-label*=", Request"],[aria-label^="NEEDS "],[aria-label^="WAITING:"],[aria-label^="BLOCKED:"],[aria-label*=", Working"],[aria-label*=", Goal"],[aria-label*=", Setting up"],[aria-label*=", Waiting"],[aria-label*=", Failed"],[aria-label*=", Limited"],[aria-label*=", Woke"],[data-sidebar-parent="shelf:working"],[data-sidebar-parent="shelf:snoozed"],[data-sidebar-parent="shelf:settled"]))):not(:has(button[aria-label="Discard draft"])))::before { content: "To read"; display: block; padding: 14px 12px 6px; font: 500 12px/16px "Montserrat", sans-serif; color: var(--bfd-muted); }

/* Who started it. T3 puts the thread id in data-thread-item; the id shape says how the thread was made. */
[data-thread-item] [data-sidebar-row] { position: relative; }
[data-thread-item] [data-sidebar-row]::after { content: "From you"; position: absolute; right: 72px; top: 9px; transition: opacity .12s var(--bfd-ease); font: 600 11px/14px "Montserrat", sans-serif; color: var(--bfd-ink); pointer-events: none; }
[data-thread-item*="launch"] [data-sidebar-row]::after { content: "From an agent"; font-weight: 500; color: var(--bfd-muted); }
[data-thread-item*="delegated-task"] [data-sidebar-row]::after { content: "Delegate"; font-weight: 500; color: var(--bfd-muted); }
[data-thread-item*="thread:project"] [data-sidebar-row]::after, [data-thread-item*="thread%3Aproject"] [data-sidebar-row]::after { content: "Scheduled"; font-weight: 500; color: var(--bfd-muted); }

[data-thread-item] [data-sidebar-row]:is(:hover,:focus-within)::after { opacity: 0; }
/* Status shows as icon plus timer. The word is dropped; a check icon means finished and not yet opened. */
[data-sidebar-row] [class*="sidebar-status-slot"] span.inline-flex.font-medium, [data-sidebar-row] [class*="sidebar-status-slot"] button.inline-flex.font-medium > span[role="status"] { font-size: 0 !important; gap: 0 !important; }
[data-sidebar-row] [class*="sidebar-status-slot"] span.inline-flex.font-medium > span { font-size: 12px; margin-left: 5px; }

/* Status is plain text: no icons, no colour. Elapsed time while working; "new" when finished and unopened (T3 gives no time for that state). */
[data-sidebar-row] [class*="sidebar-status-slot"] span.inline-flex.font-medium { color: var(--bfd-muted) !important; font-weight: 500 !important; }
[data-sidebar-row] [class*="sidebar-status-slot"] span.inline-flex.font-medium > svg:first-child { display: none !important; }
[data-sidebar-row] [class*="sidebar-status-slot"] span.inline-flex.font-medium > span { margin-left: 0; }
/* Titles stay on one line with an ellipsis so every row is the same height. The hover card shows the whole title. */
[data-testid="sidebar-row-card"] .mt-1.flex { align-items: flex-start !important; }
li[data-thread-item], [data-testid="sidebar-row-card"], [data-testid="sidebar-row-card"] > div { height: auto !important; max-height: none !important; }
[data-testid="sidebar-row-card"] .mt-1.flex .truncate { white-space: nowrap !important; overflow: hidden !important; text-overflow: ellipsis !important; line-height: 1.35; }

/* Header summary: explicit zeroes, native active rows, mutually exclusive states. */
[data-chat-header]::before { content: counter(bfdneeds) " need you  \00B7"; order: -1; flex-shrink: 0; margin-right: 8px; font: 500 12px/20px "Montserrat", sans-serif; font-variant-numeric: tabular-nums; color: var(--bfd-muted); white-space: pre; }
body:has([data-sidebar-row]:is([aria-label^="NEEDS KEITH:" i],[aria-label*=", Approval"],[aria-label*=", Input"],[aria-label*=", Request"])) [data-chat-header]::before { font-weight: 600; color: var(--bfd-gold); }
[data-chat-header]::after { content: counter(bfdupd) " to read  \00B7  " counter(bfdlive) " working"; order: -1; flex-shrink: 0; margin-right: 14px; padding-right: 14px; border-right: 1px solid var(--bfd-line); font: 500 12px/20px "Montserrat", sans-serif; font-variant-numeric: tabular-nums; color: var(--bfd-muted); white-space: pre; }

/* Touch */
[data-slot="button"], [data-toolbar-control] { transition: background-color .14s var(--bfd-ease), color .14s var(--bfd-ease), border-color .14s var(--bfd-ease), transform .08s var(--bfd-ease); }
[data-slot="button"]:active { transform: scale(.97); }
@media (prefers-reduced-motion: reduce) { [data-thread-item] [data-sidebar-row], [data-slot="button"] { transition: none !important; } }

/* QA revision: origin takes its own line; row height follows its content. */
[data-testid="sidebar-row-card"] { display: block !important; }
[data-testid="sidebar-row-card"] > div { padding-bottom: 3px !important; }
[data-thread-item] [data-sidebar-row]::after {
  position: static !important; display: block; width: auto;
  padding: 0 10px 8px; margin: 0;
  font: 500 11px/16px "Montserrat", sans-serif;
  color: var(--bfd-muted); text-align: left;
  white-space: normal; overflow-wrap: anywhere;
  opacity: 1 !important;
}
[data-thread-item] [data-sidebar-row]:is(:hover,:focus-within)::after { opacity: 1 !important; }
[data-thread-item] [data-sidebar-row]:active { transform: none !important; }
[data-thread-item] [data-sidebar-row] {
  transition: background-color .16s var(--bfd-ease), border-color .16s var(--bfd-ease);
}
[data-thread-item] [data-sidebar-row][aria-current="page"] {
  background-image: linear-gradient(var(--bfd-gold),var(--bfd-gold)) !important;
}

/* The native presentation list is a flex column. Approvals lead Needs you. */
[data-slot="sidebar"] ul[role="presentation"] > li[data-thread-item]:has([data-sidebar-row]:is([aria-label^="NEEDS KEITH:" i],[aria-label*=", Approval"],[aria-label*=", Input"],[aria-label*=", Request"])) { order: -2; }
[data-slot="sidebar"] ul[role="presentation"] > li[data-thread-item]:has([data-sidebar-row]:is([aria-label^="NEEDS KEITH: Approve send" i],[aria-label^="NEEDS KEITH: Approve release" i])) { order: -3; }
[data-slot="sidebar"] ul[role="presentation"] > li[data-thread-item]:has([data-sidebar-row] button[aria-label="Settle thread"]):not(:has([data-sidebar-row]:is([aria-label^="NEEDS KEITH:" i],[aria-label*=", Approval"],[aria-label*=", Input"],[aria-label*=", Request"],[aria-label^="NEEDS "],[aria-label^="WAITING:"],[aria-label^="BLOCKED:"],[aria-label*=", Working"],[aria-label*=", Goal"],[aria-label*=", Setting up"],[aria-label*=", Waiting"],[aria-label*=", Failed"],[aria-label*=", Limited"],[aria-label*=", Woke"],[data-sidebar-parent="shelf:working"],[data-sidebar-parent="shelf:snoozed"],[data-sidebar-parent="shelf:settled"]))):not(:has(button[aria-label="Discard draft"])) { order: -1; }
[data-slot="sidebar"] ul[role="presentation"]:has(> li[data-thread-item] [data-sidebar-row]:is([aria-label^="NEEDS KEITH: Approve send" i],[aria-label^="NEEDS KEITH: Approve release" i])) > li[data-thread-item]:has([data-sidebar-row]:is([aria-label^="NEEDS KEITH:" i],[aria-label*=", Approval"],[aria-label*=", Input"],[aria-label*=", Request"]))::before { display: none; }
[data-slot="sidebar"] ul[role="presentation"] > li:nth-child(1 of [data-thread-item]:has([data-sidebar-row]:is([aria-label^="NEEDS KEITH: Approve send" i],[aria-label^="NEEDS KEITH: Approve release" i])))::before { content: "Needs you"; display: block !important; padding: 6px 12px; font: 500 12px/16px "Montserrat", sans-serif; color: var(--bfd-muted); }
[data-thread-item] [data-sidebar-row][aria-label^="NEEDS KEITH: Approve send" i]::after { content: "Approve send"; color: var(--bfd-gold); font-weight: 600; }
[data-thread-item] [data-sidebar-row][aria-label^="NEEDS KEITH: Approve release" i]::after { content: "Approve release"; color: var(--bfd-gold); font-weight: 600; }

/* Got it is the native Settle action. Opening a row does not acknowledge it. */
[data-sidebar-row]:has(button[aria-label="Settle thread"]):not([aria-label^="NEEDS KEITH:" i],[aria-label*=", Approval"],[aria-label*=", Input"],[aria-label*=", Request"],[aria-label^="NEEDS "],[aria-label^="WAITING:"],[aria-label^="BLOCKED:"],[aria-label*=", Working"],[aria-label*=", Goal"],[aria-label*=", Setting up"],[aria-label*=", Waiting"],[aria-label*=", Failed"],[aria-label*=", Limited"],[aria-label*=", Woke"],[data-sidebar-parent="shelf:working"],[data-sidebar-parent="shelf:snoozed"],[data-sidebar-parent="shelf:settled"]):not(:has(button[aria-label="Discard draft"])) [class*="sidebar-status-slot"] { gap: 8px; }
[data-sidebar-row]:has(button[aria-label="Settle thread"]):not([aria-label^="NEEDS KEITH:" i],[aria-label*=", Approval"],[aria-label*=", Input"],[aria-label*=", Request"],[aria-label^="NEEDS "],[aria-label^="WAITING:"],[aria-label^="BLOCKED:"],[aria-label*=", Working"],[aria-label*=", Goal"],[aria-label*=", Setting up"],[aria-label*=", Waiting"],[aria-label*=", Failed"],[aria-label*=", Limited"],[aria-label*=", Woke"],[data-sidebar-parent="shelf:working"],[data-sidebar-parent="shelf:snoozed"],[data-sidebar-parent="shelf:settled"]):not(:has(button[aria-label="Discard draft"])) [class*="sidebar-status-slot"] > span { position: static !important; opacity: 1 !important; }
[data-sidebar-row]:has(button[aria-label="Settle thread"]):not([aria-label^="NEEDS KEITH:" i],[aria-label*=", Approval"],[aria-label*=", Input"],[aria-label*=", Request"],[aria-label^="NEEDS "],[aria-label^="WAITING:"],[aria-label^="BLOCKED:"],[aria-label*=", Working"],[aria-label*=", Goal"],[aria-label*=", Setting up"],[aria-label*=", Waiting"],[aria-label*=", Failed"],[aria-label*=", Limited"],[aria-label*=", Woke"],[data-sidebar-parent="shelf:working"],[data-sidebar-parent="shelf:snoozed"],[data-sidebar-parent="shelf:settled"]):not(:has(button[aria-label="Discard draft"])) [class*="sidebar-status-slot"] > span:has(button[aria-label="Settle thread"]) { pointer-events: auto !important; }
[data-sidebar-row]:has(button[aria-label="Settle thread"]):not([aria-label^="NEEDS KEITH:" i],[aria-label*=", Approval"],[aria-label*=", Input"],[aria-label*=", Request"],[aria-label^="NEEDS "],[aria-label^="WAITING:"],[aria-label^="BLOCKED:"],[aria-label*=", Working"],[aria-label*=", Goal"],[aria-label*=", Setting up"],[aria-label*=", Waiting"],[aria-label*=", Failed"],[aria-label*=", Limited"],[aria-label*=", Woke"],[data-sidebar-parent="shelf:working"],[data-sidebar-parent="shelf:snoozed"],[data-sidebar-parent="shelf:settled"]):not(:has(button[aria-label="Discard draft"])) [class*="sidebar-status-slot"] button:not([aria-label="Settle thread"]) { display: none !important; }
[data-sidebar-row]:has(button[aria-label="Settle thread"]):not([aria-label^="NEEDS KEITH:" i],[aria-label*=", Approval"],[aria-label*=", Input"],[aria-label*=", Request"],[aria-label^="NEEDS "],[aria-label^="WAITING:"],[aria-label^="BLOCKED:"],[aria-label*=", Working"],[aria-label*=", Goal"],[aria-label*=", Setting up"],[aria-label*=", Waiting"],[aria-label*=", Failed"],[aria-label*=", Limited"],[aria-label*=", Woke"],[data-sidebar-parent="shelf:working"],[data-sidebar-parent="shelf:snoozed"],[data-sidebar-parent="shelf:settled"]):not(:has(button[aria-label="Discard draft"])) button[aria-label="Settle thread"] { font-size: 0 !important; padding: 0 2px !important; background: none !important; border: none !important; color: var(--bfd-muted); }
[data-sidebar-row]:has(button[aria-label="Settle thread"]):not([aria-label^="NEEDS KEITH:" i],[aria-label*=", Approval"],[aria-label*=", Input"],[aria-label*=", Request"],[aria-label^="NEEDS "],[aria-label^="WAITING:"],[aria-label^="BLOCKED:"],[aria-label*=", Working"],[aria-label*=", Goal"],[aria-label*=", Setting up"],[aria-label*=", Waiting"],[aria-label*=", Failed"],[aria-label*=", Limited"],[aria-label*=", Woke"],[data-sidebar-parent="shelf:working"],[data-sidebar-parent="shelf:snoozed"],[data-sidebar-parent="shelf:settled"]):not(:has(button[aria-label="Discard draft"])) button[aria-label="Settle thread"] > svg { display: none !important; }
